macro_rules! deps {
    () => {
        SplitRange!();
    };
}

macro_rules! Split {
    () => {
        deps!();
        # [doc = " Split represents a partitioning of two ranges into one or more ranges. This"] # [doc = " is the secret sauce that makes a range trie work, as it's what tells us"] # [doc = " how to deal with two overlapping but unequal ranges during insertion."] # [doc = ""] # [doc = " Essentially, either two ranges overlap or they don't. If they don't, then"] # [doc = " handling insertion is easy: just insert the new range into its"] # [doc = " lexicographically correct position. Since it does not overlap with anything"] # [doc = " else, no other transitions are impacted by the new range."] # [doc = ""] # [doc = " If they do overlap though, there are generally three possible cases to"] # [doc = " handle:"] # [doc = ""] # [doc = " 1. The part where the two ranges actually overlap. i.e., The intersection."] # [doc = " 2. The part of the existing range that is not in the new range."] # [doc = " 3. The part of the new range that is not in the old range."] # [doc = ""] # [doc = " (1) is guaranteed to always occur since all overlapping ranges have a"] # [doc = " non-empty intersection. If the two ranges are not equivalent, then at"] # [doc = " least one of (2) or (3) is guaranteed to occur as well. In some cases,"] # [doc = " e.g., `[0-4]` and `[4-9]`, all three cases will occur."] # [doc = ""] # [doc = " This `Split` type is responsible for providing (1), (2) and (3) for any"] # [doc = " possible pair of byte ranges."] # [doc = ""] # [doc = " As for insertion, for the overlap in (1), the remaining ranges to insert"] # [doc = " should be added by following the corresponding transition. However, this"] # [doc = " should only be done for the overlapping parts of the range. If there was"] # [doc = " a part of the existing range that was not in the new range, then that"] # [doc = " existing part must be split off from the transition and duplicated. The"] # [doc = " remaining parts of the overlap can then be added to using the new ranges"] # [doc = " without disturbing the existing range."] # [doc = ""] # [doc = " Handling the case for the part of a new range that is not in an existing"] # [doc = " range is seemingly easy. Just treat it as if it were a non-overlapping"] # [doc = " range. The problem here is that if this new non-overlapping range occurs"] # [doc = " after both (1) and (2), then it's possible that it can overlap with the"] # [doc = " next transition in the current state. If it does, then the whole process"] # [doc = " must be repeated!"] # [doc = ""] # [doc = " # Details of the 3 cases"] # [doc = ""] # [doc = " The following details the various cases that are implemented in code"] # [doc = " below. It's plausible that the number of cases is not actually minimal,"] # [doc = " but it's important for this code to remain at least somewhat readable."] # [doc = ""] # [doc = " Given [a,b] and [x,y], where a <= b, x <= y, b < 256 and y < 256, we define"] # [doc = " the follow distinct relationships where at least one must apply. The order"] # [doc = " of these matters, since multiple can match. The first to match applies."] # [doc = ""] # [doc = "   1. b < x <=> [a,b] < [x,y]"] # [doc = "   2. y < a <=> [x,y] < [a,b]"] # [doc = ""] # [doc = " In the case of (1) and (2), these are the only cases where there is no"] # [doc = " overlap. Or otherwise, the intersection of [a,b] and [x,y] is empty. In"] # [doc = " order to compute the intersection, one can do [max(a,x), min(b,y)]. The"] # [doc = " intersection in all of the following cases is non-empty."] # [doc = ""] # [doc = "    3. a = x && b = y <=> [a,b] == [x,y]"] # [doc = "    4. a = x && b < y <=> [x,y] right-extends [a,b]"] # [doc = "    5. b = y && a > x <=> [x,y] left-extends [a,b]"] # [doc = "    6. x = a && y < b <=> [a,b] right-extends [x,y]"] # [doc = "    7. y = b && x > a <=> [a,b] left-extends [x,y]"] # [doc = "    8. a > x && b < y <=> [x,y] covers [a,b]"] # [doc = "    9. x > a && y < b <=> [a,b] covers [x,y]"] # [doc = "   10. b = x && a < y <=> [a,b] is left-adjacent to [x,y]"] # [doc = "   11. y = a && x < b <=> [x,y] is left-adjacent to [a,b]"] # [doc = "   12. b > x && b < y <=> [a,b] left-overlaps [x,y]"] # [doc = "   13. y > a && y < b <=> [x,y] left-overlaps [a,b]"] # [doc = ""] # [doc = " In cases 3-13, we can form rules that partition the ranges into a"] # [doc = " non-overlapping ordered sequence of ranges:"] # [doc = ""] # [doc = "    3. [a,b]"] # [doc = "    4. [a,b], [b+1,y]"] # [doc = "    5. [x,a-1], [a,b]"] # [doc = "    6. [x,y], [y+1,b]"] # [doc = "    7. [a,x-1], [x,y]"] # [doc = "    8. [x,a-1], [a,b], [b+1,y]"] # [doc = "    9. [a,x-1], [x,y], [y+1,b]"] # [doc = "   10. [a,b-1], [b,b], [b+1,y]"] # [doc = "   11. [x,y-1], [y,y], [y+1,b]"] # [doc = "   12. [a,x-1], [x,b], [b+1,y]"] # [doc = "   13. [x,a-1], [a,y], [y+1,b]"] # [doc = ""] # [doc = " In the code below, we go a step further and identify each of the above"] # [doc = " outputs as belonging either to the overlap of the two ranges or to one"] # [doc = " of [a,b] or [x,y] exclusively."] # [derive (Clone , Debug , Eq , PartialEq)] struct Split { partitions : [SplitRange ; 3] , len : usize , }
    };
}

Split!()